def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def decorator(func):
        cache = {}
        memos = OrderedDict()
        hits = misses = 0
        lock = Lock()

        def decorated(self, *args, **kwargs):
            nonlocal hits, misses
            key = (args, frozenset(kwargs.items())) if typed else (args, kwargs)
            with lock:
                try:
                    memo = memos[key]
                    if (
                        memo.ttl <= 1
                        or memo.ts <= timer() - ttl
                        or len(memos) >= maxsize
                    ):
                        del memos[key]
                        raise KeyError
                    memos.move_to_end(key, last=False)
                except KeyError:
                    hits += 1
                    memo = FunctionMemo(
                        func=func, ts=timer(), ttl=ttl, args=args, kwargs=kwargs
                    )
                    memos[key] = memo
                    return cache[key] = memo.value
                else:
                    misses += 1
                    value = memo.value
                    memo.ts += timer() - memo.ts
                    return value

        return decorated
    return decorator
```

