def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves up to `maxsize` results based on a Least Frequently Used (LFU) algorithm."""

    _cache = {}
    _freqs = {}
    _loops = 0

    def _entry(key):
        nonlocal _cache, _freqs, _loops
        if key not in _cache:
            return None
        _freqs[key] = _loops
        _loops += 1
        return _cache[key]

    def _least_frequent(items):
        nonlocal _loops
        return min(items, key=lambda k: (_freqs.get(k, -_loops - 1), k))

    def _populate_cache(result, *args, **kwargs):
        nonlocal _cache, _freqs, _loops
        key = (args, frozenset(kwargs.items())) if typed else args
        if key not in _cache and len(_cache) == maxsize:
            key_to_pop = _least_frequent(_cache)
            del _cache[key_to_pop]
            if key_to_pop in _freqs:
                del _freqs[key_to_pop]
        _cache[key] = result
        _freqs.setdefault(key, _loops)
        _loops += 1

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, frozenset(kwargs.items())) if typed else args
            result = _entry(key)
            if result is None:
                result = func(*args, **kwargs)
                _populate_cache(result, *args, **kwargs)
            return result

        return wrapper

    return decorator
```

