def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorated(function):
        memo = {}
        hits = {}
        misses = set()

        def decorated_function(*args):
            if typed and len(args) > 0:
                key = (type(args[0]), args[0])
            else:
                key = args

            if key in memo:
                hits[key] += 1
                return memo[key]
            else:
                result = function(*args)
                memo[key] = result
                misses.add(key)

                # remove least frequently used from cache
                if len(misses) >= maxsize:
                    to_remove = min(misses, key=lambda k: hits[k])
                    del memo[to_remove]
                    hits[to_remove] = 0
                    misses.remove(to_remove)

            return result
        return decorated_function
    return decorated
