    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Initialize a set to store the minimum bases
    min_bases = set()
    # Iterate through each class in the classes list
    for cls in classes:
        # Check if the class is already in the minimum bases set
        if cls not in min_bases:
            # Add the class to the minimum bases set
            min_bases.add(cls)
            # Get the class's base classes
            base_classes = cls.__bases__
            # Iterate through each base class
            for base_cls in base_classes:
                # If the base class is not already in the minimum bases set, add it
