    custom_observer_schema = app.spec.manifest.get(
        'observer_schema_source', 'krake.data.observer_schema.get_default_observer_schema'
    )

    # If the custom observer schema is not present, use the default observer schema
    if not custom_observer_schema:
        custom_observer_schema = 'krake.data.observer_schema.get_default_observer_schema'

    # Get the observer schema for each resource in the application specification
    resource_dict = {}
    for resource_name, resource_spec in app.spec.manifest.items():
        # If a custom observer schema is present for the resource, use it
        if resource_spec.get('observer_schema'):
            resource_dict[resource_name] = resource_spec['observer_schema']
        # Otherwise, use the default observer schema
        else:
            resource_dict[resource_name] = custom_observer_schema

