    if self.get_version() - 1 != prior.get_version():
        raise ValueError("prior version must be prior to the current version of the current inventory object")
    # Validate that all items in prior inventory are still present in the current inventory
    for item in prior.get_items():
        if not self.get_item(item.get_id()):
            raise ValueError(f"Item {item.get_id()} is missing from current inventory")
    # Validate that all items in prior inventory have the same quantity as in the current inventory
    for item in prior.get_items():
        if self.get_item(item.get_id()).get_quantity() != item.get_quantity():
            raise ValueError(f"Quantity of item {item.get_id()} has been changed")
    # Validate that all prior inventory tags are still present in the current inventory
    for tag in prior.get_tags():
        if not self.get_tag(tag.get_name()):
            raise ValueError(f"Tag {tag.get_name()} is missing from current inventory")
    # Validate that all prior inventory tags have the same number of items as in the current inventory
    for tag in prior.get_tags():
