def validate_fixity(self, fixity, manifest_files):
    # Check if the fixity block is present in the inventory
    if not fixity:
        return False

    # Make sure that the fixity block is a list
    if not isinstance(fixity, list):
        raise InvalidInventory("Fixity block is not a list")

    # Make sure that the fixity block has the required keys
    required_keys = ["time", "type", "name", "bytes", "hash"]
    for key in required_keys:
        if key not in fixity:
            raise InvalidInventory("Fixity block is missing key: " + key)

    # Validate the time field
    time_type = type(fixity["time"])
    if time_type is not str:
        raise InvalidInventory("Invalid time field type: " + str(time_type))
    try:
        datetime.strptime(fixity["time"], "%Y-%m-%d %H:%M:%S")
    except ValueError:
        raise InvalidInventory("Invalid time field format: " + fixity["time"])

    # Validate the type field
    if not fixity["type"] in ["sha256", "md5"]:
        raise InvalidInventory("Invalid type field: " + fixity["type"])

    # Validate the name field
    if not fixity["name"] in manifest_files:
        raise InvalidInventory("Invalid name field: " + fixity["name"])

    # Validate the bytes field
    bytes_type = type(fixity["bytes"])
    if bytes_type is not int:
        raise InvalidInventory("Invalid bytes field type: " + str(bytes_type))

    # Validate the hash field
    if not re.match(r"^[a-fA-F0-9]{32,64}$", fixity["hash"]):
        raise InvalidInventory("Invalid hash field: " + fixity["hash"])

    # Return true if the fixity block is valid
    return True

def validate_fixity(self, fixity, manifest_files):
    if not isinstance(fixity, dict):
        raise TypeError(f"Expected a dict, got {type(fixity)}")

    if not isinstance(manifest_files, list):
        raise TypeError(f"Expected a list, got {type(manifest_files)}")

    if "files" not in fixity:
        raise ValueError(f"Missing 'files' property in fixity block: {fixity}")

    fixity_files = fixity["files"]
    if not isinstance(fixity_files, list):
        raise TypeError(f"Expected a list, got {type(fixity_files)}")

    for file in fixity_files:
        if file not in manifest_files:
            raise ValueError(f"File {file} is not listed in the manifest")

    return fixity

