/**
 *
 * @param {string} source The source
 * @param {string[]} xmls A list of XML filenames
 * @param {string[]} files A list of files in the folder/zipfile
 * @returns {object} A dictionary with the key being the name of the XML files and the value being a package
 */
function _group_files_by_xml_filename(source, xmls, files) {
  // Create an empty dictionary to store the result
  var raw_entries = {};

  // Iterate over the list of XML filenames
  for (let i = 0; i < xmls.length; i++) {
    // Get the current XML filename
    const current_xml_filename = xmls[i];

    // Extract the filename without the extension
    const basename = current_xml_filename.slice(0, current_xml_filename.lastIndexOf('.'));

    // Group the files based on the current XML filename
    const grouped_files = files.filter(file => file.slice(0, file.lastIndexOf('.')) === basename);

    // Add the grouped_files to the dictionary with the corresponding XML filename as the key
    raw_entries[current_xml_filename] = grouped_files;
  }

  return raw_entries;
}

