def extract_number_and_supplement_from_issue_element(issue):
    number = None
    supplement = None
    if issue is not None:
        issue_text = issue.strip()
        if issue_text.startswith('<issue'):
            issue_text = issue_text[len('<issue'):]
        if issue_text.endswith('</issue>'):
            issue_text = issue_text[:-len('</issue>')]
        issue_text = issue_text.strip()
        issue_words = issue_text.split(' ')
        for word in issue_words:
            if word.endswith(' Spe'):
                number = int(word[:-len(' Spe')])
                supplement = 'Spe'
            elif word.endswith(' Suppl'):
                number = int(word[:-len(' Suppl')])
                supplement = 'Suppl'
            elif word.endswith('spe'):
                number = int(word[:-len('spe')])
                supplement = 'spe'
        if number is not None and supplement is not None:
            return (number, supplement)
    return None
