def absorb(self, args):
    new_args = []
    for arg in args:
        if "~A & ~B" in arg:
            new_args.append("~A & B")
        elif "~A | ~B" in arg:
            new_args.append("~A | B")
        elif "A & B" in arg:
            new_args.append("A & B")
        elif "A | B" in arg:
            new_args.append("A | B")
        else:
            new_args.append(arg)
    return new_args
