def _fromutc(self, dt):
    if dt.tzinfo.utcoffset(dt) is not None:
        raise ValueError("Input parameter must be a UTC datetime")
    else:
        newdt = super().fromutc(dt)
        is_duplicate = (newdt.utcoffset().nanoseconds == 0) or (newdt.utcoffset().nanoseconds == 7200000000000)
        if is_duplicate:
            newdt = newdt.replace(fold=1)
        return newdt
