def guess_style(pieces):
    # Check if the version pieces contain a separator
    if any(sep in pieces for sep in ['-', '+', '~', '.', '_']):
        # If so, return "path" style
        return 'path'
    # If not, return "calver" style
    return 'calver'

# Strategy to automatically detect the style of version pieces
def auto_style(pieces):
