def render_pieces(pieces, target_style):
    # Get the rendering strategy for the target style
    render_strategy = STYLE_MAP.get(target_style)
    # If the strategy doesn't exist, return the pieces as is
    if not render_strategy:
        return pieces
    # Otherwise, apply the rendering strategy
    return render_strategy(pieces)

