def validate_version_inventories(version_dirs):
    # Check that each version directory has an inventory file
    for version_dir in version_dirs:
        if not os.path.isfile(version_dir + "/inventory.md"):
            return False

    # Read the root inventory
    root_inventory = parse_inventory(os.path.join(version_dirs[0], "inventory.md"))

    # Check that each subsequent inventory is valid
    for version_dir, i in enumerate(version_dirs[1:], start=1):
        inventory = parse_inventory(os.path.join(version_dir, "inventory.md"))

        # Check that the version number is correct
        if int(inventory["version"]["number"]) != i:
            return False

        # Check that the content digests are the same
        if inventory["version"]["digest"] != root_inventory["version"]["digest"]:
            return False

    # If we reach this point, all inventories are valid
    return True

