def validate_version_inventories(self, version_dirs):
    for version_dir in version_dirs:
        if not os.path.exists(os.path.join(self.root_dir, version_dir)):
            raise ValueError(f"No directory named {version_dir} found in root_dir")
        version_list = self.get_version_list()
        if version_dir not in version_list:
            raise ValueError(f"{version_dir} is not in the version list")
        # Check if the inventory file exists for this version.
        inventory_file_path = os.path.join(self.root_dir, version_dir, "inventory.json")
        if not os.path.isfile(inventory_file_path):
            raise ValueError(f"No inventory file found in {version_dir}")
        # Get the content digests from the inventory file.
        inventory = self.get_inventory_contents(inventory_file_path)
        for content in inventory:
            # Check if the content digest is different from the root inventory.
            if content.get("digest") not in self.root_inventory.get("items"):
                self.different_content[content.get("digest")] = content
    return self.different_content
