def deep_merge_nodes(nodes: list[tuple[ruamel.yaml.nodes.ScalarNode, Any]]) -> list[tuple[ruamel.yaml.nodes.ScalarNode, Any]]:
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    """
    final_nodes = {}
    for node in nodes:
        key, value = node
        if key in final_nodes:
            # If the key already exists, deep merge the nodes
            final_node = final_nodes[key]
            if isinstance(final_node, ruamel.yaml.nodes.MappingNode):
                final_node.update(value)
        else:
            # If the key doesn't exist, add it to the final nodes dict
            final_nodes[key] = value
    return list(final_nodes.items())
