def bash_completion():
    """
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    """
    import borg.main
    import borg.args

    command_parser = borg.main.get_command_parser()
    for name, args_parser in command_parser.commands.items():
        if name.startswith("__"):
            continue
        yield args_parser.name
        for action in sorted(args_parser._actions, key=lambda x: x.option_strings):
            if not isinstance(action, argparse._SubParsersAction):
                continue
            for name2, args_parser2 in action.choices.items():
                if name2.startswith("_"):
                    continue
                yield f"{name2}:"
                for action2 in sorted(args_parser2._actions, key=lambda x: x.option_strings):
                    yield f"    {action2.option_strings}:"
                    if action2.choices is not None:
                        for choice in sorted(action2.choices, key=lambda x: x):
                            yield f"        {choice}:"
                            if action2.type is not None and action2.metavar is not None:
