def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:

    """
    image_id = ""
    netloc = ""
    use_ssl = False

    if image_href.startswith("image://"):
        image_href = image_href[8:]

    if image_href.startswith("ssl://"):
        image_href = image_href[6:]
        use_ssl = True

    if "@" in image_href:
        image_id, _, netloc = image_href.rpartition("@")
    else:
        netloc, _, image_id = image_href.rpartition("/")

    if not image_id or not netloc:
        raise ValueError("Invalid image href: {}".format(image_href))

    return (image_id, netloc, use_ssl)
