    # Make sure the candidate claims that it provides the interface
    if not tentative:
        if not iface.providedBy(candidate):
            raise zope.interface.Invalid("Instance does not provide the specified interface")

    # Make sure the candidate defines all the necessary methods
    for name, _ in iface.getMethods().items():
        if name not in candidate:
            raise zope.interface.Invalid("Method {} is not defined".format(name))

