def isoparse(dt_str):
    date, time, offset = dt_str.split('T')
    year, month, day = date.split('-')
    hour, minute, second = time.split(':')
    if time[-1] in [',', '.']:
        microsecond = time[-6:-1]
    else:
        microsecond = 0
    if date[-1] == 'W':
        year, week, day = date.split('-W')
        date = dateutil.parser.parse(f'{year}-{week}') + datetime.timedelta(days=day)
    else:
        date = datetime.date(int(year), int(month), int(day))
    if time[:2] == '24':
        hour = 0
    time = datetime.time(int(hour), int(minute), int(second), int(microsecond))
    if offset == 'Z':
        tz = dateutil.tz.tzutc()
    else:
        hours, minutes = offset.split(':')
        tz = dateutil.tz.tzoffset(offset, hours, minutes)
    dt = datetime.datetime.combine(date, time)
    dt.replace(tzinfo=tz)
    return dt
